/*
 * A395442  Squares visited by six knights, all starting on square 1, when
 *          moving on a square-spiral numbered board and always moving to the
 *          lowest available unvisited square.
 * https://oeis.org/A395442
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, fini, full
 * Formula:   a(n) = the sequence of squares visited by six knights on a
 *            square‑spiral board, * as described in OEIS A395442. The
 *            sequence is generated by simulation
 * Range:     u8 n <= 186, u16 n <= 7984, u32 n <= 7984, u64 n <= 7984,
 *            u128 n <= 7984, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>

static const int64_t KNIGHT_DX[8] = {1, 2, 2, 1, -1, -2, -2, -1};
static const int64_t KNIGHT_DY[8] = {2, 1, -1, -2, -2, -1, 1, 2};

/* Convert a coordinate (x,y) on the square spiral to its square number.
 * The numbering starts at (0,0)=1, then moves right, up, left, left, down, down, right, right, etc. */
static idx_t coord_to_index(int64_t x, int64_t y)
{
    if (x == 0 && y == 0) return 1;
    int64_t ax = x < 0 ? -x : x;
    int64_t ay = y < 0 ? -y : y;
    int64_t r   = ax > ay ? ax : ay;              /* ring number */
    int64_t sideLen = 2 * r;
    idx_t   maxNum   = (uint64_t)(2 * r + 1) * (uint64_t)(2 * r + 1); /* (2r+1)^2 */
    idx_t   minIndex = maxNum - 8 * r + 1;        /* smallest index on this ring */

    if (x == r && y != -r)          /* right side (including top right corner) */
    {
        idx_t offset = (idx_t)(y + r - 1);
        return minIndex + offset;
    }
    if (y == r && x != r)           /* top side (excluding top right corner) */
    {
        idx_t offset = (idx_t)(r - 1 - x);
        return minIndex + sideLen + offset;
    }
    if (x == -r && y != r)          /* left side (excluding top left corner) */
    {
        idx_t offset = (idx_t)(r - 1 - y);
        return minIndex + 2 * sideLen + offset;
    }
    /* bottom side (including bottom left corner and bottom right corner) */
    {
        idx_t offset = (idx_t)(x + r - 1);
        return minIndex + 3 * sideLen + offset;
    }
}

/* Push a value onto a dynamic sequence, allocating more space as needed. */
static void push_seq(seq_t **seq, size_t *len, size_t *cap, seq_t val)
{
    if (*len == *cap) {
        *cap = (*cap == 0) ? 16 : (*cap << 1);
        *seq = (seq_t*)realloc(*seq, (*cap) * sizeof(seq_t));
    }
    (*seq)[*len] = val;
    (*len)++;
}

/* Main sequence function. */
seq_t a(idx_t n) {
    static seq_t *cache = NULL;
    static size_t cache_len = 0;
    static bool initialized = false;

    if (!initialized) {
        /* Simulation data */
        static size_t visited_cap = 2000000;          /* initial capacity */
        static bool *visited = NULL;
        visited = (bool*)calloc(visited_cap, sizeof(bool));

        /* Knight state */
        static int64_t pos_x[6] = {0,0,0,0,0,0};
        static int64_t pos_y[6] = {0,0,0,0,0,0};
        static bool active[6]  = {true,true,true,true,true,true};
        size_t active_cnt = 6;

        /* Sequence buffer */
        size_t seq_cap = 0;
        seq_t *seq = NULL;
        size_t seq_len = 0;

        /* Start square */
        pos_x[0] = pos_y[0] = 0;
        visited[1] = true;
        push_seq(&seq, &seq_len, &seq_cap, (seq_t)1);

        while (active_cnt) {
            for (size_t k = 0; k < 6; ++k) {
                if (!active[k]) continue;

                idx_t best_idx = (idx_t)-1;   /* MAX value */
                int64_t best_x = 0, best_y = 0;

                for (int m = 0; m < 8; ++m) {
                    int64_t nx = pos_x[k] + KNIGHT_DX[m];
                    int64_t ny = pos_y[k] + KNIGHT_DY[m];
                    idx_t idx = coord_to_index(nx, ny);

                    if (idx >= visited_cap) {
                        size_t old_cap = visited_cap;
                        visited_cap = idx + 1024;                 /* grow a bit beyond requested */
                        visited = (bool*)realloc(visited, visited_cap * sizeof(bool));
                        memset(visited + old_cap, 0, (visited_cap - old_cap) * sizeof(bool));
                    }

                    if (!visited[idx] && idx < best_idx) {
                        best_idx = idx;
                        best_x = nx;
                        best_y = ny;
                    }
                }

                if (best_idx == (idx_t)-1) {
                    active[k] = false;
                    active_cnt--;
                } else {
                    visited[best_idx] = true;
                    push_seq(&seq, &seq_len, &seq_cap, (seq_t)best_idx);
                    pos_x[k] = best_x;
                    pos_y[k] = best_y;
                }
            }
        }

        cache = seq;
        cache_len = seq_len;
        initialized = true;
        free(visited);
    }

    if (n == 0 || n > cache_len) return 0;
    return cache[n - 1];
}
